from collections import deque

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Check if start or goal is out of bounds or is an obstacle
    if not (0 <= start[0] < rows and 0 <= start[1] < cols):
        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Use DFS to find a path
    visited = set()
    path = []

    def dfs(r, c, path_so_far):
        if (r, c) == goal:
            path.extend(path_so_far)
            return True
        visited.add((r, c))
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) not in visited and grid[nr][nc] == '.':
                    path_so_far.append((nr, nc))
                    if dfs(nr, nc, path_so_far):
                        return True
                    path_so_far.pop()
        return False

    if not dfs(start[0], start[1], [start]):
        return []

    return path

